package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="conversaciones_internas")
public class ConversacionInterna{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="cin_id")private Long id;@Column(name="cin_asu",nullable=false,length=200)private String asunto;@Column(name="cin_fec_cre",nullable=false)private LocalDateTime fechaCreacion;@Column(name="cin_fec_ult",nullable=false)private LocalDateTime fechaUltima;@Column(name="cin_fec_baj")private LocalDateTime fechaBaja;@Column(name="usu_id_baj")private Long usuarioBajaId;@Column(name="cin_act",nullable=false)private Boolean activa=true;public Long getId(){return id;}public String getAsunto(){return asunto;}public void setAsunto(String v){asunto=v;}public LocalDateTime getFechaCreacion(){return fechaCreacion;}public void setFechaCreacion(LocalDateTime v){fechaCreacion=v;}public LocalDateTime getFechaUltima(){return fechaUltima;}public void setFechaUltima(LocalDateTime v){fechaUltima=v;}public LocalDateTime getFechaBaja(){return fechaBaja;}public void setFechaBaja(LocalDateTime v){fechaBaja=v;}public Long getUsuarioBajaId(){return usuarioBajaId;}public void setUsuarioBajaId(Long v){usuarioBajaId=v;}public Boolean getActiva(){return activa;}public void setActiva(Boolean v){activa=v;}}
